import{_ as t,o as s,c as a,a2 as i}from"./chunks/framework.CNDaxUod.js";const u=JSON.parse('{"title":"Deployment","description":"","frontmatter":{},"headers":[],"relativePath":"guide/deployment.md","filePath":"guide/deployment.md"}'),o={name:"guide/deployment.md"};function n(r,e,d,l,h,p){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="deployment" tabindex="-1">Deployment <a class="header-anchor" href="#deployment" aria-label="Permalink to &quot;Deployment&quot;">​</a></h1><p>AsyncUp is one small container — by default with SQLite inside, so there are no external moving parts at all. Google Chat needs to reach it on a public HTTPS URL.</p><blockquote><p>Looking for a walkthrough? The <strong><a href="./server-setup.html">Setup guide</a></strong> covers every scenario — VPS, Postgres, Cloud Run, homelab — with a decision matrix and production checklist. This page is the building-blocks reference.</p></blockquote><h2 id="database-embedded-or-bring-your-own" tabindex="-1">Database: embedded or bring your own <a class="header-anchor" href="#database-embedded-or-bring-your-own" aria-label="Permalink to &quot;Database: embedded or bring your own&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mode</th><th>Configuration</th><th>When to choose it</th></tr></thead><tbody><tr><td><strong>Embedded SQLite</strong> (default)</td><td><code>DB_PATH</code> on a persistent volume</td><td>Simplest possible ops: one container, one file to back up. Plenty for any team size AsyncUp serves</td></tr><tr><td><strong>Bring your own PostgreSQL</strong></td><td><code>DATABASE_URL=postgres://…</code></td><td>You already run managed Postgres (RDS, Cloud SQL, Neon, Supabase, …) and want its backups/HA, or your platform has no persistent volumes (e.g. some scale-to-zero setups)</td></tr><tr><td><strong>Postgres on the same machine</strong></td><td><code>docker compose --profile postgres up -d</code> + <code>DATABASE_URL=postgres://asyncup:…@postgres:5432/asyncup</code></td><td>Postgres semantics without leaving the box</td></tr></tbody></table><p>Setting <code>DATABASE_URL</code> skips SQLite entirely; the schema is created and migrated automatically on startup in both modes. The full test suite runs against both engines in CI on every change.</p><h2 id="system-requirements" tabindex="-1">System requirements <a class="header-anchor" href="#system-requirements" aria-label="Permalink to &quot;System requirements&quot;">​</a></h2><p>AsyncUp idles at a once-a-minute scheduler tick; load is a few webhook calls per person per day. CPU architecture: amd64 or arm64.</p><table tabindex="0"><thead><tr><th>Setup</th><th>Minimum</th><th>Recommended</th></tr></thead><tbody><tr><td>App + SQLite</td><td>1 vCPU (shared is fine), 256 MB RAM, 1 GB disk</td><td>1 vCPU, <strong>512 MB RAM</strong>, 5 GB disk</td></tr><tr><td>App + bundled Postgres</td><td>1 vCPU, 768 MB RAM, 3 GB disk</td><td><strong>2 vCPU, 2 GB RAM</strong>, 10 GB disk</td></tr><tr><td>App with external/managed DB</td><td>1 vCPU, 256 MB RAM</td><td>1 vCPU, 512 MB RAM</td></tr></tbody></table><p>Realistic sizing: the Node process uses ~100–150 MB RSS; the image is ~300 MB; a year of standups for a 50-person team is well under 100 MB of data. The smallest VPS tier (or Cloud Run&#39;s 512 MB default) is comfortably enough — teams into the hundreds of users don&#39;t change this picture.</p><h2 id="prebuilt-image" tabindex="-1">Prebuilt image <a class="header-anchor" href="#prebuilt-image" aria-label="Permalink to &quot;Prebuilt image&quot;">​</a></h2><p>Multi-arch images (<code>linux/amd64</code>, <code>linux/arm64</code>) are published to GHCR on every merge to <code>main</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ghcr.io/asyncup-dev/asyncup:latest</span></span></code></pre></div><p>Tags: <code>latest</code> (main), <code>vX.Y.Z</code> + <code>X.Y</code> (releases), <code>sha-…</code> (every build) — pin a digest for reproducible deploys. Building from source stays a one-liner (<code>docker build -t asyncup .</code>) if you prefer auditing what you run.</p><h2 id="docker-compose-simplest" tabindex="-1">Docker Compose (simplest) <a class="header-anchor" href="#docker-compose-simplest" aria-label="Permalink to &quot;Docker Compose (simplest)&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # set DASHBOARD_TOKEN + SECRET_KEY</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # pulls the GHCR image by default</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># then finish setup in https://&lt;host&gt;/app (sign in with DASHBOARD_TOKEN)</span></span></code></pre></div><p>Put it behind any HTTPS reverse proxy (Caddy, nginx, Traefik) and point the Chat app at <code>https://&lt;your-host&gt;/chat/events</code>. The SQLite data lives in the <code>standup-data</code> volume.</p><p>A 1-shared-CPU VPS or a free-tier VM is plenty — the bot is idle except for a once-a-minute scheduler tick and your team&#39;s submissions.</p><h2 id="scale-to-zero-cloud-run" tabindex="-1">Scale-to-zero (Cloud Run) <a class="header-anchor" href="#scale-to-zero-cloud-run" aria-label="Permalink to &quot;Scale-to-zero (Cloud Run) {#scale-to-zero-cloud-run}&quot;">​</a></h2><p>Closest thing to &quot;no servers at all&quot;, and realistically $0/month at team scale on the free tier:</p><ol><li>Deploy the container to <strong>Cloud Run</strong> (min instances = 0, <strong>max instances = 1</strong> — the in-process scheduler must not run twice). Use a managed Postgres via <code>DATABASE_URL</code> (Cloud SQL, or Neon&#39;s free tier) — Cloud Run&#39;s filesystem is ephemeral and network volumes don&#39;t support SQLite locking reliably.</li><li>The in-process scheduler only runs while an instance is alive, so drive it externally: create a <strong>Cloud Scheduler</strong> job (free tier covers it) that hits <code>POST /tick</code> every minute with header <code>Authorization: Bearer &lt;tick token&gt;</code>.</li><li>Generate the tick token in dashboard → Settings → Access tokens.</li></ol><p>Webhook events (dialog opens, submissions, commands) spin the instance up on demand; <code>/tick</code> wakes it for prompts, reminders, and deadlines. Ticks are idempotent — overlapping or missed ticks are safe and caught up on the next one.</p><h2 id="bare-bun" tabindex="-1">Bare Bun <a class="header-anchor" href="#bare-bun" aria-label="Permalink to &quot;Bare Bun&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --production</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PORT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">8080</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> DB_PATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/var/lib/asyncup/standup.db</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/index.ts</span></span></code></pre></div><p>Run it under systemd or any process manager.</p><h2 id="production-checklist" tabindex="-1">Production checklist <a class="header-anchor" href="#production-checklist" aria-label="Permalink to &quot;Production checklist&quot;">​</a></h2><ul><li>[ ] Guided setup finished at <code>/app/setup</code>: project number and service-account key verified, first signed Chat event received</li><li>[ ] HTTPS in front of <code>/chat/events</code> (Google only delivers to https)</li><li>[ ] Google or SAML sign-in configured, then the setup token switched off under <em>Settings › Sign-in &amp; SSO</em></li><li>[ ] Tick token generated if <code>/tick</code> is internet-reachable; <code>SECRET_KEY</code> backed up</li><li>[ ] <code>DB_PATH</code> on persistent storage, backed up (or <code>DATABASE_URL</code> pointing at managed Postgres)</li></ul>`,27)])])}const k=t(o,[["render",n]]);export{u as __pageData,k as default};
